Here's a self-contained spiral galaxy canvas animation:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Spiral Galaxy</title>
<style>
  html, body { margin: 0; height: 100%; background: #000; overflow: hidden; }
  canvas { display: block; width: 100vw; height: 100vh; }
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
(function () {
  const canvas = document.getElementById('sky');
  const ctx = canvas.getContext('2d');
  let W, H, cx, cy;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    cx = W / 2;
    cy = H / 2;
  }
  window.addEventListener('resize', resize);
  resize();

  // ---- Galaxy parameters ----
  const NUM_STARS = 900;
  const ARMS = 2;                 // number of spiral arms
  const TWIST = 4.2;              // how tightly the arms wind
  const SPREAD = 0.55;            // scatter around each arm (radians-ish)
  const MAX_R = Math.min(W, H) * 0.46;

  const stars = [];

  function makeStar() {
    // Bias radius distribution toward the core (more stars near center)
    const r = Math.pow(Math.random(), 1.7) * MAX_R;
    const armIndex = Math.floor(Math.random() * ARMS);
    // Base angle along the logarithmic spiral arm
    const baseAngle = (armIndex / ARMS) * Math.PI * 2 + r * TWIST / MAX_R * 2.4;
    // Scatter around the arm — tighter near center, looser at edges
    const scatter = (Math.random() + Math.random() + Math.random() - 1.5) * SPREAD * (0.4 + r / MAX_R);
    const angle = baseAngle + scatter;

    // Orbital speed: roughly flat rotation curve, slight randomness
    const speed = (0.10 + Math.random() * 0.05) * (1.6 / (0.5 + r / MAX_R * 1.4));

    // Size & brightness — brighter toward the core
    const size = 0.5 + Math.random() * 1.6;
    const coreGlow = Math.max(0, 1 - r / (MAX_R * 0.55));
    const bright = 0.35 + Math.random() * 0.4 + coreGlow * 0.5;

    // Color variation: blue-white outer, warm yellow-orange inner
    let cr, cg, cb;
    const t = Math.min(1, r / MAX_R);
    if (Math.random() < 0.12) {
      // a few red giants scattered anywhere
      cr = 255; cg = 140 + Math.random() * 60; cb = 110;
    } else if (t < 0.4) {
      cr = 255; cg = 200 + Math.random() * 40; cb = 140 + Math.random() * 60;
    } else {
      cr = 170 + Math.random() * 60; cg = 190 + Math.random() * 50; cb = 255;
    }

    return {
      r: r,
      angle: angle,
      speed: speed,
      size: size,
      bright: Math.min(1, bright),
      cr: cr, cg: cg, cb: cb,
      twinklePhase: Math.random() * Math.PI * 2,
      twinkleSpeed: 0.5 + Math.random() * 2.5
    };
  }

  for (let i = 0; i < NUM_STARS; i++) stars.push(makeStar());

  // Static background dust: faint distant stars
  const dust = [];
  for (let i = 0; i < 250; i++) {
    dust.push({
      x: Math.random(), y: Math.random(),
      size: Math.random() * 0.8,
      bright: 0.08 + Math.random() * 0.18,
      phase: Math.random() * Math.PI * 2,
      speed: 0.3 + Math.random() * 1.2
    });
  }

  let last = performance.now();

  function draw(now) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;

    // Fade previous frame for soft motion trails
    ctx.fillStyle = 'rgba(0, 0, 0, 0.28)';
    ctx.fillRect(0, 0, W, H);

    // ---- Background dust ----
    for (const d of dust) {
      const tw = 0.6 + 0.4 * Math.sin(now / 1000 * d.speed + d.phase);
      ctx.fillStyle = 'rgba(200, 210, 255,' + (d.bright * tw).toFixed(3) + ')';
      ctx.fillRect(d.x * W, d.y * H, d.size, d.size);
    }

    // ---- Galactic core glow ----
    const coreR = MAX_R * 0.22;
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, coreR);
    g.addColorStop(0, 'rgba(255, 245, 220, 0.9)');
    g.addColorStop(0.25, 'rgba(255, 220, 160, 0.45)');
    g.addColorStop(0.6, 'rgba(255, 190, 120, 0.12)');
    g.addColorStop(1, 'rgba(255, 180, 100, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
    ctx.fill();

    // ---- Stars ----
    for (const s of stars) {
      s.angle += s.speed * dt;
      const x = cx + Math.cos(s.angle) * s.r;
      const y = cy + Math.sin(s.angle) * s.r * 0.62; // slight elliptical tilt for depth

      const tw = 0.72 + 0.28 * Math.sin(now / 1000 * s.twinkleSpeed + s.twinklePhase);
      const a = s.bright * tw;

      ctx.fillStyle = 'rgba(' + (s.cr | 0) + ',' + (s.cg | 0) + ',' + (s.cb | 0) + ',' + a.toFixed(3) + ')';
      ctx.beginPath();
      ctx.arc(x, y, s.size, 0, Math.PI * 2);
      ctx.fill();
    }

    requestAnimationFrame(draw);
  }

  requestAnimationFrame(draw);
})();
</script>
</body>
</html>
```

**How it works:**

- **Spiral structure** — stars are placed along logarithmic spiral arms (`angle = arm offset + r × twist`), with Gaussian-like scatter that tightens near the core and loosens at the edges, so arms read clearly but feel organic.
- **Rotation** — each star orbits with a speed that falls off with radius (a rough flat rotation curve), driven by delta-time so the motion is frame-rate independent.
- **Color variation** — inner stars lean warm yellow/orange, outer stars lean blue-white, plus scattered red giants; brightness also increases toward the core.
- **Twinkle** — every star has its own sine phase and speed modulating its alpha each frame.
- **Core glow** — a radial gradient paints the bright galactic bulge each frame.
- **Trails & depth** — a semi-transparent black fill each frame leaves soft motion trails, and the galaxy is drawn with a slight vertical squash for a tilted-disc feel. A layer of faint static dust stars adds background depth.
